static void UseEnumerator(PgSqlConnection myConnection) {
  PgSqlCommand cmd = new PgSqlCommand("SELECT comm FROM Test.emp");
  cmd.Connection = myConnection;
  myConnection.Open();
  try {
    PgSqlDataReader reader = cmd.ExecuteReader();
    IEnumerator enumerator = reader.GetEnumerator();

    while (enumerator.MoveNext()) {
      if (((IDataRecord)enumerator.Current).IsDBNull(0)) {
        Console.WriteLine("Null value found");
      }
    }
    reader.Close();
  }
  finally {
    myConnection.Close();
  }
}

static void GetSchemaFromReader(PgSqlConnection myConnection) {
  PgSqlCommand cmd = new PgSqlCommand("SELECT * FROM Test.emp, Test.Dept");
  cmd.Connection = myConnection;
  myConnection.Open();
  try {
    PgSqlDataReader reader = cmd.ExecuteReader(CommandBehavior.KeyInfo);

    DataTable dt = reader.GetSchemaTable();
    //...

    reader.Close();
  }
  finally {
    myConnection.Close();
  }
}

