This sample shows how to use DbDataSet. The routine accepts DbDataSet-compatible object and connection string. After s were created and populated, they were added to DataTableCollection of DbDataSet, and DataRelation was created to link tables. pubic void FillDataSet(DbDataSet dataSet, string connStr) {
        // retrieving data from DEPT table
        PgSqlDataTable dept = new PgSqlDataTable("select * from dept", connStr);
        dept.FetchAll = true;
        dept.Active = true;

        // retrieving data from EMP table
        PgSqlDataTable emp = new PgSqlDataTable("select * from emp", connStr);
        emp.FetchAll = true;
        emp.Active = true;

        // adding data tables to PgSqlDataSet
        dataSet.Tables.Add(dept);
        dataSet.Tables.Add(emp);

        // linking tables to allow navigation from parent table rows
        // to corresponding child table rows
        DataColumn parentColumn = dataSet.Tables["DEPT"].Columns["DEPTNO"];
        DataColumn childColumn = dataSet.Tables["EMP"].Columns["DEPTNO"];
        DataRelation relation =        new System.Data.DataRelation("DeptsEmps",
                parentColumn, childColumn);
        dataSet.Relations.Add(relation);
} Public Sub FillDataSet(ByRef dataSet As DbDataSet, ByVal connStr As String)
        ' retrieving data from DEPT table
        Dim dept As New PgSqlDataTable("select * from dept", connStr)
        dept.FetchAll = True
        dept.Active = True

        ' retrieving data from EMP table
        Dim emp As New PgSqlDataTable("select * from emp", connStr)
        emp.FetchAll = True
        emp.Active = True

        ' adding data tables to PgSqlDataSet
        dataSet.Tables.Add(dept)
        dataSet.Tables.Add(emp)

        ' linking tables to allow navigation from parent table rows
        ' to corresponding child table rows
        Dim parentColumn As DataColumn = dataSet.Tables("DEPT").Columns("DEPTNO")
        Dim childColumn As DataColumn = dataSet.Tables("EMP").Columns("DEPTNO")
        Dim relation As New System.Data.DataRelation("DeptsEmps", parentColumn, childColumn)
        dataSet.Relations.Add(relation)
End Sub

This sample shows how to use . The routine accepts DbTable-compatible object and IDbConnection implementor object as parameters. After SQL query text has been set, the data is retrieved from the table. static void UseDataTable(DbDataTable myDataTable, IDbConnection myConnection)
{
  myDataTable.Connection = myConnection;
  myDataTable.SelectCommand = myConnection.CreateCommand();
  myDataTable.SelectCommand.CommandText = "SELECT * FROM Test.Dept";
  try
  {
    myDataTable.Fill();
    myDataTable.Rows[1].Delete();
    myDataTable.Update();
    foreach(DataRow myRow in myDataTable.Rows)
    {
      foreach(DataColumn myCol in myDataTable.Columns)
      {
        Console.Write(myRow[myCol] + "\t");
      }
      Console.WriteLine();
    }
  }
  finally
  {
    myDataTable.Clear();
  }
} Public Sub UseDataTable(ByVal myDataTable As DbDataTable, ByVal myConnection As IDbConnection)
  myDataTable.Connection = myConnection
  myDataTable.SelectCommand = myConnection.CreateCommand()
  myDataTable.SelectCommand.CommandText = "SELECT * FROM Test.Dept"
  Try
    myDataTable.Fill()
    myDataTable.Rows(1).Delete()
    myDataTable.Update()
    Dim myRow As DataRow
    Dim myCol As DataColumn
    For Each myRow In myDataTable.Rows
      For Each myCol In myDataTable.Columns
        Console.Write(myRow(myCol) & Chr(9))
      Next myCol
      Console.WriteLine()
    Next myRow
  Finally
    myDataTable.Clear()
  End Try
End Sub

