This sample shows how to use . The routine accepts DbTable-compatible object, IDbCommand implementor object, and IDbConnection implementor object as parameters. After SQL query text has been set the data is retrieved from the table. public void UseDataTable(DbDataTable myDataTable, DbCommand myCommand, DbConnection myConnection)
{
  myDataTable.Connection = myConnection;
  myCommand.CommandText = "SELECT * FROM Test.Dept";
  myDataTable.SelectCommand = myCommand;
  try
  {
    myDataTable.Active = true;
    foreach(DataRow myRow in myDataTable.Rows)
    {
      foreach(DataColumn myCol in myDataTable.Columns)
      {
        Console.Write(myRow[myCol]+"\t");
      }
      Console.WriteLine();
    }
  }
  finally
  {
    myDataTable.Active = false;
  }
} Public Sub UseDataTable(ByVal myDataTable As DbDataTable, ByVal myCommand As DbCommand, ByVal myConnection As DbConnection)
  myDataTable.Connection = myConnection
  myCommand.CommandText = "SELECT * FROM Test.Dept"
