This sample shows how to use paged access to data. It attempts to read rows 11 through 20 from the table and to display them. However, if quantity of records in the table is less than 20, only available rows will be filled into . Number of rows actually added is rendered to console. public void FillDataTable(DbDataTable myDataTable, IDbConnection myConnection)
{
  myDataTable.Connection = myConnection;
  myDataTable.SelectCommand = myConnection.CreateCommand();
  myDataTable.SelectCommand.CommandText = "SELECT EmpNo, EName FROM Test.Emp";
  try
  {
    Console.WriteLine(myDataTable.FillPage(10,10) + " rows filled.");
    foreach(DataRow myRow in myDataTable.Rows)
    {
      foreach(DataColumn myCol in myDataTable.Columns)
      {
        Console.Write(myRow[myCol]+"\t");
      }
      Console.WriteLine();
    }
  }
  finally
  {
    myDataTable.Clear();
  }
} Public Sub FillDataTable(ByVal myDataTable As DbDataTable, ByVal myConnection As IDbConnection)
  myDataTable.Connection = myConnection
  myDataTable.SelectCommand = myConnection.CreateCommand()
  myDataTable.SelectCommand.CommandText = "SELECT EmpNo, EName FROM Test.Emp"
  Try
    Console.WriteLine(myDataTable.FillPage(10, 10) & " rows filled.")
    Dim myRow As DataRow
    Dim myCol As DataColumn
    For Each myRow In myDataTable.Rows
      For Each myCol In myDataTable.Columns
        Console.Write(myRow(myCol) & Chr(9))
      Next myCol
      Console.WriteLine()
    Next myRow
  Finally
    myDataTable.Clear()
  End Try
End Sub

