  myDataTable.SelectCommand.CommandText = "SELECT * FROM Test.Dept";

  IAsyncResult aRes = myDataTable.BeginFill(null, null);

  Console.Write("Fetch in process");

  Thread.Sleep(100);
  myDataTable.SuspendFill(true);
  Console.Write("Fetch is stopped");

  myDataTable.EndFill(aRes);
  Console.Write("All records are fetched");
} Private Shared Sub UseDataTable3(ByVal myDataTable As DbDataTable, ByVal myConnection As DbConnection)
  myDataTable.Connection = myConnection
  myDataTable.SelectCommand = myConnection.CreateCommand
  myDataTable.SelectCommand.CommandText = "SELECT * FROM Test.Dept"
  Dim result1 As IAsyncResult = myDataTable.BeginFill(Nothing, Nothing)
  Console.Write("Fetch in process")
  Thread.Sleep(100)
  myDataTable.SuspendFill(True)
  Console.Write("Fetch is stopped")
  myDataTable.EndFill(result1)
  Console.Write("All records are fetched")
End Sub

The following example demonstrates how to use the  property. static void UseDataTable(DbDataTable myDataTable, DbConnection myConnection) {

  myDataTable.Connection = myConnection;
  myDataTable.SelectCommand = myConnection.CreateCommand();
  myDataTable.SelectCommand.CommandText = "SELECT * FROM Dept";
  myDataTable.NonBlocking = true;
  myDataTable.Active = true;

  while ( true ) {
    Thread.Sleep(100);
    bool isFetching = !System.Threading.Monitor.TryEnter(myDataTable.SyncRoot, 0);
    if (!isFetching)
      System.Threading.Monitor.Exit(myDataTable.SyncRoot);
    else
      break;
    Console.Write("Fetch in process");
  }
  Console.Write("All records are fetched");
} Private Shared Sub UseDataTable(ByVal myDataTable As DbDataTable, ByVal myConnection As DbConnection)
  myDataTable.Connection = myConnection
  myDataTable.SelectCommand = myConnection.CreateCommand
  myDataTable.SelectCommand.CommandText = "SELECT * FROM Dept"
  myDataTable.NonBlocking = True
  myDataTable.Active = True
  Do While True
    Thread.Sleep(100)
    If Not Monitor.TryEnter(myDataTable.SyncRoot, 0) Then
      Console.Write("All records are fetched")
      Return
    End If
    Monitor.Exit(myDataTable.SyncRoot)
    Console.Write("Fetch in process")
  Loop
End Sub

The following code adds two records to a table and updates them. The table is rendered then to console. static void UpdateATable(DbDataTable myDataTable, IDbConnection myConnection)
{
  myDataTable.Connection = myConnection;
  myDataTable.SelectCommand = myConnection.CreateCommand();
  myDataTable.SelectCommand.CommandText = "SELECT EmpNo, EName FROM Test.Emp";
  try
  {
    myDataTable.Active = true;
    DataRow[] newRows = new DataRow[2];
    newRows[0] = myDataTable.Rows.Add(new object[] {20000,"Jefferson"});
    newRows[1] = myDataTable.Rows.Add(new object[] {20001,"Jameson"});
    myDataTable.UpdateRows(newRows);

    foreach(DataRow myRow in myDataTable.Rows)
    {
      foreach(DataColumn myCol in myDataTable.Columns)
      {
        Console.Write(myRow[myCol]+"\t");
      }
      Console.WriteLine();
    }
  }
  finally
  {
    myDataTable.Active = false;
  }
} Public Sub UpdateATable(ByVal myDataTable As DbDataTable, ByVal myConnection As IDbConnection)
  myDataTable.Connection = myConnection
  myDataTable.SelectCommand = myConnection.CreateCommand()
  myDataTable.SelectCommand.CommandText = "SELECT EmpNo, EName FROM Test.Emp"
  Try
    myDataTable.Active = True
    Dim newVal1() As Object = {20000, "Jefferson"}
    Dim newVal2() As Object = {20001, "Jameson"}
    Dim newRows(1) As DataRow
    newRows(0) = myDataTable.Rows.Add(newVal1)
    newRows(1) = myDataTable.Rows.Add(newVal2)
    myDataTable.UpdateRows(newRows)

    Dim myRow As DataRow
    Dim myCol As DataColumn
    For Each myRow In myDataTable.Rows
      For Each myCol In myDataTable.Columns
        Console.Write(myRow(myCol) & Chr(9))
      Next myCol
      Console.WriteLine()
    Next myRow
  Finally
    myDataTable.Active = False
  End Try
End Sub

The following example demonstrates how to use the  property. static void UseDataTable(DbDataTable myDataTable, DbConnection myConnection) {

  myDataTable.Connection = myConnection;
  myDataTable.SelectCommand = myConnection.CreateCommand();
  myDataTable.SelectCommand.CommandText = "SELECT e.EMPNO, e.ENAME, e.JOB, d.DNAME 
        FROM Test.Dept d, Test.Emp e 
        where d.Deptno = e.Deptno";

  myDataTable.FetchAll = true;
  myDataTable.CachedUpdates = false;
  myDataTable.UpdatingTable = "Test.Emp";
  myDataTable.UpdatingKeyFields = "EMPNO";
  myDataTable.UpdatingFields = "EMPNO;ENAME;JOB";

  myDataTable.Open();

  DataRow row = myDataTable.Rows[0];
  row[myDataTable.Columns["ENAME"]] = "John Smith";

  myDataTable.Update();
  myDataTable.Close();
} Private Shared Sub UseDataTable(ByVal myDataTable As DbDataTable, ByVal myConnection As DbConnection)
