public void GetDataColumns(PgSqlConnection pgConnection)
{

  pgConnection.Open();
  PgSqlLoader loader = new PgSqlLoader();
  loader.Connection = pgConnection;
  loader.TableName = "load_table";
  PgSqlLoaderColumn myColumn;
  try
