member.example:
Following example displays all loader columns. public void DisplayColumns(string tableName, PgSqlConnection conn) {

  // Create loader instance
  PgSqlLoader loader = new PgSqlLoader();

  // Set up working connection
  // Connection must be opened
  loader.Connection = conn;

  // Set up table name for loading
  loader.TableName = tableName;

  // Create column collection for loading table
  loader.CreateColumns();

  // Iterate through column collection
  foreach (PgSqlLoaderColumn column in loader.Columns)
    Console.WriteLine(column.Name);
} Public Sub DisplayColumns(tableName as string, conn as PgSqlConnection)

  ' Create loader instance
  Dim loader as PgSqlLoader = new PgSqlLoader()

  ' Set up working connection
  ' Connection must be opened
  loader.Connection = conn

  ' Set up table name for loading
  loader.TableName = tableName

  ' Create column collection for loading table
  loader.CreateColumns()

  ' Iterate through column collection
  Dim column as PgSqlLoaderColumn
  For Each column in loader.Columns
    Console.WriteLine(column.Name)
  Next
End Sub

The following example searches for a  within a . If the column exists, the example displays the index of the column. If the column does not exist, the example displays an error. This example assumes that a  has already been created. public void SearchMyColumns() {
  // ...
  // create PgSqlLoaderColumnCollection myColumns and PgSqlLoaderColumn myNewColumn
  // ...
  if (!myColumns.Contains((Object) myNewColumn))
    MessageBox.Show("ERROR: no such column in the collection");
  else
    MessageBox.Show("match on column #" +
      myColumns.IndexOf((Object) myNewColumn).ToString());
} Public Sub SearchMyColumns()
  ' ...
  ' create PgSqlLoaderColumnCollection myColumns and PgSqlLoaderColumn myNewColumn
  ' ...
  If Not myColumns.Contains(CType(myNewColumn, Object)) Then
    MessageBox.Show("ERROR: no such column in the collection")
  Else
    MessageBox.Show("match on column #" & myColumns.IndexOf(CType(myNewColumn, Object)).ToString())
  End If
End Sub 'SearchMyColumns

The following example exports the  to an array of  objects, doubles the size of the array by using  and returns the collection. It then clears the collection, and returns  if the columns are no longer persisting. This example assumes that a  has already been created. public bool DoubleYourColumns() {
  // ...
  // create PgSqlLoaderColumnCollection myColumns
  // ...
  PgSqlLoaderColumn[] myColumnArray = new PgSqlLoaderColumn[(2*myColumns.Count) - 1];
  myColumns.CopyTo(myColumnArray, 0);
  myColumns.CopyTo(myColumnArray, myColumns.Count);
  myColumns.Clear();
  return true;
} Public Function DoubleYourColumns() As Boolean
  ' ...
  ' create PgSqlLoaderColumnCollection myColumns
  ' ...
  Dim myColumnArray(2 * myColumns.Count - 1) As PgSqlLoaderColumn
  myColumns.CopyTo(myColumnArray, 0)
  myColumns.CopyTo(myColumnArray, myColumns.Count)
  myColumns.Clear()
  Return True
End Function 'DoubleYourColumns

