The following sample shows how to enable and disable monitoring of database activity in your application. static void OnEvent(object sender, MonitorEventArgs e)
{
  if (e.TracePoint==MonitorTracePoint.BeforeEvent)
  {
    Console.WriteLine("Description: " + e.Description);
    Console.WriteLine(" Extra info: " + e.ExtraInfo);
  }
}


[MTAThread]
static void Main(string[] args)
{
  PgSqlConnection pgConn = new PgSqlConnection(
      "host=server;database=test;user id=postgres;");
  PgSqlMonitor pgMonitor = new PgSqlMonitor();
  pgMonitor.TraceEvent += new MonitorEventHandler(OnEvent);
  pgMonitor.IsActive = true;
  PgSqlCommand pgCommand = new PgSqlCommand("select count(*) from Dept",pgConn);
  pgConn.Open();
  Console.WriteLine(pgCommand.ExecuteScalar());
  pgConn.Close();
  pgMonitor.TraceEvent -= new MonitorEventHandler(OnEvent);
  Console.ReadLine();
} Sub OnEvent(ByVal sender As Object, ByVal e As MonitorEventArgs)
  If e.TracePoint = MonitorTracePoint.BeforeEvent Then
    Console.WriteLine("Description: " & e.Description)
    Console.WriteLine(" Extra info: " & e.ExtraInfo)
  End If
End Sub

<MTAThread()> _
Sub Main()
  Dim pgConn As PgSqlConnection = New PgSqlConnection( _
      "host=server;database=test;user id=postgres;")
  Dim pgMonitor As PgSqlMonitor = New PgSqlMonitor
  AddHandler pgMonitor.TraceEvent, AddressOf OnEvent
  pgMonitor.IsActive = True
  Dim pgCommand As PgSqlCommand = New PgSqlCommand("select count(*) from Dept", pgConn)
  pgConn.Open()
  Console.WriteLine(pgCommand.ExecuteScalar())
  pgConn.Close()
  RemoveHandler pgMonitor.TraceEvent, AddressOf OnEvent
  Console.ReadLine()
End Sub

member.remarks:

Use  to consecutively execute several SQL statements stored in  property.  allows to execute them all at once or one by one. You can use  event to monitor execution flow and  to catch errors.


There are three ways to execute a script:



-  using  method;



-  using  method;



-  using . method.

For more information refer to corresponding method.

member.example:
This sample shows how to retrieve collection of statements that make up the script and execute them one by one. string script =
  "DROP TABLE DEPT;"+
  "CREATE TABLE DEPT ("+
  "  DEPTNO INT PRIMARY KEY,"+
  "  DNAME VARCHAR(14),"+
  "  LOC VARCHAR(13)"+
  ")WITH OIDS;"+
  "INSERT INTO DEPT VALUES (10,'ACCOUNTING','NEW YORK');"+
  "INSERT INTO DEPT VALUES (20,'RESEARCH','DALLAS');"+
  "INSERT INTO DEPT VALUES (30,'SALES','CHICAGO');"+
  "INSERT INTO DEPT VALUES (40,'OPERATIONS','BOSTON');"+
  "SELECT * FROM DEPT";
PgSqlConnection pgConn = new PgSqlConnection(
    "host=server;database=test;user id=postgres;");
PgSqlScript pgScript = new PgSqlScript(script,pgConn);
SqlStatementCollection pgColl = pgScript.Statements;
IDataReader pgReader;
pgConn.Open();
foreach (SqlStatement pgStatement in pgColl)
{
  Console.WriteLine(pgStatement.Text);
  try
  {
    pgReader = pgStatement.Execute();
    Console.WriteLine("  Records affected " + pgReader.RecordsAffected); 
    while (pgReader.Read()) 
    { 
      Console.WriteLine(pgReader.GetString(0)); 
    } 
    pgReader.Close(); 
    Console.WriteLine();
  }
  catch
  {
    Console.WriteLine("  Failed");
  }
}
pgConn.Close(); Dim script As String = _
  "DROP TABLE DEPT;" + _
  "CREATE TABLE DEPT (" + _
  "  DEPTNO INT PRIMARY KEY," + _
  "  DNAME VARCHAR(14)," + _
  "  LOC VARCHAR(13)" + _
  ")WITH OIDS;" + _
    "INSERT INTO DEPT VALUES (10,'ACCOUNTING','NEW YORK');" + _
    "INSERT INTO DEPT VALUES (20,'RESEARCH','DALLAS');" + _
    "INSERT INTO DEPT VALUES (30,'SALES','CHICAGO');" + _
    "INSERT INTO DEPT VALUES (40,'OPERATIONS','BOSTON');" + _
    "SELECT * FROM DEPT"
Dim pgConn As PgSqlConnection = New PgSqlConnection( _
    "host=server;database=test;user id=postgres;")
Dim pgScript As PgSqlScript = New PgSqlScript(script, pgConn)
Dim pgColl As SqlStatementCollection = pgScript.Statements
Dim pgReader As IDataReader
pgConn.Open()
For Each pgStatement As SqlStatement In pgColl
  Console.WriteLine(pgStatement.Text)
  Try
    pgReader = pgStatement.Execute()
    Console.WriteLine("  Records affected " & pgReader.RecordsAffected)
    While pgReader.Read()
      Console.WriteLine(pgReader.GetString(0))
    End While
    pgReader.Close()
    Console.WriteLine()
  Catch ex As Exception
    Console.WriteLine("  Failed")
  End Try
Next pgStatement
pgConn.Close()

